self.KB_CONTENT["card:782246"]={"id":"card:782246","ty":"card","sourceId":"782246","title":"『取替代料件建立作業』的作業目的為何？","ver":"GP4以上","topic":"製令","keywords":["製令","計劃","用量","元件"],"y":"explain","answer":"1.當元件於主件中有取替代件時，可於此作業先行建立，於列印相關用量報表時列印出或物料需求計劃展算時納入可用量計算或於製令展開後查詢取用。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[782246,778769],"file":"kb-cards.jsonl"};
