self.KB_CONTENT["card:785056"]={"id":"card:785056","ty":"card","sourceId":"785056","title":"『固定資產查詢作業』中的『折舊方法 (MB023)』為何？","ver":"GP4以上","topic":"資產","keywords":["資產","固定","折舊"],"y":"other","answer":"* 分為0.不提折舊、1.平均法及2.定率遞減法三種方式。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
