self.KB_CONTENT["card:770988"]={"id":"card:770988","ty":"card","sourceId":"770988","title":"工程完工批次/拋轉還原-EPMB05』產生的傳票是否可以修改？","ver":"GP4X","topic":"傳票","keywords":["傳票","拋轉","作廢","完工"],"y":"other","answer":"不可以，當傳票的【來源碼】為“A2:完工結轉“時，此張傳票不可刪除、不可修改、不可作廢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
