self.KB_CONTENT["card:778311"]={"id":"card:778311","ty":"card","sourceId":"778311","title":"『製令在製材料明細表』中的『分類方式』為何？","ver":"GP4以上","topic":"明細表","keywords":["明細表","製令","材料","分類"],"y":"other","answer":"* 共用參數設定作業中分類方式有1.商品分類方式一、2.商品分類方式二、3.商品分類方式三及4.商品分類方式四。非空白者對應的設定資料，直接顯示出欄位資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
