self.KB_CONTENT["card:783447"]={"id":"card:783447","ty":"card","sourceId":"783447","title":"『票據融資查詢作業』中的『還息方式 (TH010)』為何？","ver":"GP4以上","topic":"票據","keywords":["票據","固定","每月","融資"],"y":"other","answer":"* 分別為1.每月固定日計息、2.到期計息、3.每月相對日計息及9.其他。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
