self.KB_CONTENT["card:813270"]={"id":"card:813270","ty":"card","sourceId":"813270","title":"盤點單少了很多品號， 請問要如何跑出來","ver":"iGP 1.0.7.以上","topic":"品號","keywords":["品號","庫存","盤點","出來"],"y":"howto","answer":"若數量為0也要盤點，執行『抽盤品號產生作業』要勾選【帳面庫存量為零之品號盤點】","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
